import argparse
XOFF_TABLE = '<repo>/nn_x/w10/r2/premise/g_noend_pos_oe.json'
XT_PRESETS = {'cv': ['seq_cv_invd20', 'seq_cv_w5', 'seq_cv_fwd5', 'seq_cv_t1', 'seq_cv_seqs', 'seq_cv_pop', 'seq_cv_norm', 'seq_cv_invd20_rk', 'seq_cv_invd20_z', 'it_hist_all_luo', 'it_hist_all_luo_rk', 'it_hist_all_luo_z', 'it_hist_et1_luo', 'it_hist_et2_luo', 'it_hist_et3_luo', 'it_hist_et4_luo']}
XT_REL = {'cvraw': ['seq_cv_invd20', 'it_hist_all_luo'], 'cvnd': ['seq_cv_invd20', 'it_hist_all_luo']}
XT_RELONLY = {'cvnd_prew': ['prew_fe', 'prew_new', 'prew_hmax32'], 'cvnd_pre2': ['pre2_fe', 'pre2_new', 'pre2_hmax32', 'pre2_id_contrib']}
def parse():
    p = argparse.ArgumentParser()
    p.add_argument('--variant', default='base')
    p.add_argument('--d', type=int, default=128)
    p.add_argument('--heads', type=int, default=4)
    p.add_argument('--blocks', type=int, default=2)
    p.add_argument('--hist_layers', type=int, default=1)
    p.add_argument('--drop', type=float, default=0.1)
    p.add_argument('--no_hist', action='store_true')
    p.add_argument('--no_set', action='store_true')
    p.add_argument('--no_pos', action='store_true', help='disable the position tower')
    p.add_argument('--loss', default='softmax', choices=['softmax', 'bce', 'both'])
    p.add_argument('--loss_norm', default='batch', choices=['batch', 'feed', 'idcg'], help='listwise loss normalisation (K1): per-batch mean / equal per-feed weight / x K/IDCG(K)')
    p.add_argument('--max_hist', type=int, default=256)
    p.add_argument('--train_feeds', type=int, default=0, help='subsample train feeds (0 = all)')
    p.add_argument('--epochs', type=float, default=1.0)
    p.add_argument('--lr', type=float, default=0.001)
    p.add_argument('--wd', type=float, default=0.02)
    p.add_argument('--warmup', type=int, default=500)
    p.add_argument('--cand_budget', type=int, default=32768)
    p.add_argument('--max_feeds', type=int, default=512)
    p.add_argument('--eval_every', type=int, default=1000)
    p.add_argument('--seed', type=int, default=0)
    p.add_argument('--no_test', action='store_true')
    p.add_argument('--aux_pos', type=float, default=0.0, help='weight of auxiliary production-position regression')
    p.add_argument('--aux_mode', default='mse', choices=['mse', 'listwise'], help='aux production-order target: MSE on pos/(M-1) or listwise CE toward softmax(-pos/tau) (K9)')
    p.add_argument('--aux_tau', type=float, default=10.0)
    p.add_argument('--ff', type=int, default=2, help='FFN width multiplier')
    p.add_argument('--sim_bias', type=int, default=0, nargs='?', const=1, help='1: per-head scaled raw cosine bias in target attention; 2: + per-event-type scale/prior, same-category and recency biases')
    p.add_argument('--prand_base', type=float, default=-1.0, help='>=0: per-feed loss weight = prand_base + p_random (exploration/random-order train feeds, eda/labels_position/out/train_prandom.npz; p=0 for M<50 or NaN); aux loss weighted by 1-p')
    p.add_argument('--only_random', type=float, default=-1.0, help='>=0: train only on feeds with p_random > this value (e.g. stage-2 continued training)')
    p.add_argument('--keep', default='best', choices=['best', 'last'], help='checkpoint to keep: best val eval (default) or the last step (no selection on val)')
    p.add_argument('--intent', type=float, default=0.0, help="N3: weight of the category-intent aux loss (predict the category distribution of the feed's positives from user+history; log P(cand category) is fed to the candidates)")
    p.add_argument('--xt', default='', help="train-stage extra features: preset 'cv' (leak-safe co-visitation + leave-user-out popularity) or a comma list of data/feats names")
    p.add_argument('--arch', default='tf', choices=['tf', 'gru', 'din'], help='tf: transformer history encoder + cross/set attention; gru: bi-GRU history encoder; din: DIN MLP attention + SiLU pooling + DCNv2 cross head, no set attention')
    p.add_argument('--attn_gate', action='store_true', help='gated attention (elementwise sigmoid output gate)')
    p.add_argument('--retr_m', type=int, default=0, help='nnx A4: TabR-style retrieval over the top-m history items')
    p.add_argument('--muon', action='store_true', help='nnx C2: Muon (RMS-matched to AdamW) for hidden 2-D Linear weights (needs split k/v projections, set automatically)')
    p.add_argument('--sched', default='cos', choices=['cos', 'wsd'], help='nnx C4: lr schedule (wsd = 1-sqrt cooldown)')
    p.add_argument('--cooldown_frac', type=float, default=0.2, help='nnx C4: fraction of steps in the WSD cooldown')
    p.add_argument('--cooldown_mix', type=float, default=0.0, help='nnx C4: probability of drawing an exploration-feed batch at each cooldown step')
    p.add_argument('--aux_anneal', type=float, default=-1.0, help='nnx C4: >=0: aux weight annealed from --aux_pos to this value with the cooldown lr')
    p.add_argument('--id_buckets', type=int, default=0, help='N4: hashed item-ID residual table size (0 = off)')
    p.add_argument('--id_drop', type=float, default=0.5)
    p.add_argument('--id_hist_only', action='store_true', help='item-ID embeddings only in history tokens')
    p.add_argument('--xt_drop', type=float, default=0.0, help='ID-input dropout: blank all --xt inputs of this fraction of train candidates (cold simulation)')
    p.add_argument('--user0', action='store_true', help='K5: add is_user0 and is_user0*log(1+H) dense features')
    p.add_argument('--domain', action='store_true', help='K2: traffic-domain token (train: production soft-mixed to random-like by p_random)')
    p.add_argument('--holdout', type=int, default=0, help='item 4: hold out this many random-like train feeds (p_random>0.9, M>=50, fixed seed) from training and evaluate on them')
    p.add_argument('--select_on', default='val', choices=['val', 'holdout'], help='checkpoint selection metric')
    p.add_argument('--save_steps', default='', help='W1: comma list of steps (eval steps) at which to also save ckpt/<variant>@<step>.pt (snapshot ensembles)')
    p.add_argument('--init', default='', help='initialize weights (and architecture) from nn/ckpt/<name>.pt')
    p.add_argument('--pos_mode', default='both', choices=['both', 'rev', 'pos'], help="position tower terms: g(pos)+g'(M-1-pos) / only end-of-feed g'(M-1-pos) / only g(pos)")
    p.add_argument('--time_limit', type=float, default=0, help='stop training after this many minutes')
    p.add_argument('--attn_drop', type=float, default=-1.0, help='r6 adrop0: attention-probability dropout in every attention block (<0: same as --drop)')
    p.add_argument('--retr_prod', action='store_true', help='r6 a4w: add the product term T3(k_c * k_j) to A4 values')
    p.add_argument('--retr_uniq', action='store_true', help='r6 a4u: A4 retrieval over distinct items (newest occurrence), fp32 scores, repeat-count value')
    p.add_argument('--retr_tcnt', action='store_true', help='r6 a4u+: with --retr_uniq, per-event-type occurrence counts of each retrieved item (value + logit)')
    p.add_argument('--cretr_m', type=int, default=0, help='r6 cset: TabR retrieval over the top-m same-feed candidates')
    p.add_argument('--set_sim_bias', action='store_true', help='r6 cset: cosine prior in the candidate set attention')
    p.add_argument('--typed_cross', action='store_true', help='r6 typed: last cross block attends to the user token + target actions (event_type 1, source 1)')
    p.add_argument('--drop_cd', type=float, default=-1.0, help='wave-2 d0/d20: >=0: dropout p on EVERY dropout site (Block FFN + residual, retrieval value MLP and attention-probability dropout) from the cooldown start (step t_cool; step 0 with --cooldown_frac 1.0, i.e. right after --init). Exact; the checkpoint cfg keeps its drop')
    p.add_argument('--pool_p', type=float, default=0.5, help='wave-2 pp02: cooldown exploration pool = training feeds (holdout excluded; M>=50 since p_random is 0 for M<50) with p_random > this (default 0.5 = the nn/train.py pool)')
    p.add_argument('--aug_cand', type=float, default=0.0, help='wave-2 aug (r6_external R2): on cooldown POOL batches only, per feed q ~ U(aug_cand, 1) and each negative candidate kept w.p. q, all positives kept (0 = off; values >= 1 are also a no-op)')
    p.add_argument('--aug_hist', type=float, default=0.0, help='wave-2 aug (R2): on cooldown POOL batches only, drop each history event w.p. this (0 = off)')
    p.add_argument('--hcap', default='', help="wave-4 hcap (P5): per-event-type history caps 'type:cap,...' (newest kept, compacted) on every training batch from the cooldown start and on the selection holdout; '' = off")
    p.add_argument('--rec_q', type=float, default=0.0, help='wave-4 rec33 (P4): prob. that a NON-pool cooldown batch comes from the last --rec_days train days (holdout excluded); 0 = off')
    p.add_argument('--rec_days', type=int, default=3, help='wave-4 rec33: number of last train days (MSK) (with --rec_q)')
    p.add_argument('--rho_file', default='', help="wave-4 rho70 (P3): excess file (rho_score.py) of this --init snapshot; NON-pool cooldown batches sample the top --rho_keep production feeds by excess + the pool-eligible feeds; '' = off")
    p.add_argument('--rho_keep', type=float, default=0.7, help='wave-4 rho70: kept share of production feeds')
    p.add_argument('--trunc_off', type=float, default=0.0, help='wave-5 TRUNC-PROD: a > 0 adds a * L[group, rkend] * (1 - p_soft) (rkend 0-2, production groups M<50 / M>=50, trunc_lift.json) to the main listwise logits of TRAINING batches only; 0 = off')
    p.add_argument('--trunc_lifts', default='', help="wave-5 TRUNC-PROD M-bucket lifts: json (review/make_trunc_lifts.py, e.g. nn_x/w5/trunc_lifts_mbucket.json) whose per-M-bucket production lifts replace the M<50 / M>=50 groups of --trunc_off (needs --trunc_off > 0); '' = off")
    p.add_argument('--aux_norm', default='batch', choices=['batch', 'feed'], help='wave-5 AUXF: K9 aux normalisation; batch = live weighted per-batch mean (off), feed = aux_norm_c * sum_f (1-p_f) CE_aux_f / max_feeds')
    p.add_argument('--aux_norm_c', type=float, default=1.695, help='wave-5 AUXF constant (keeps the epoch-mean aux weight; labels_loss out/10_aux_norm_const.txt)')
    p.add_argument('--cliplog', type=int, default=0, help='wave-5 CLIPLOG: N > 0 logs the pre-clip grad norm every step and the main / aux grad norms every N steps (diagnostic; no effect on training); 0 = off')
    p.add_argument('--save_last', action='store_true', help='wave-5 hygiene: also keep the LAST checkpoint ckpt/<v>@last.pt with its val / holdout (/ test) preds')
    p.add_argument('--save_holdout', action='store_true', help='wave-5 hygiene (r7 port): write preds/holdout/nn_<v>_holdout.npy of the selected checkpoint')
    p.add_argument('--select_min_step', type=int, default=0, help='wave-5 hygiene: checkpoint selection only among evals at step >= this (0 = off)')
    p.add_argument('--hzcd', action='store_true', help='wave-5 hzcd (INSIGHTS item 6, cd_arms6.py): from the cooldown start (step t_cool; step 0 with --cooldown_frac 1.0) every TRAINING batch (regular and pool) reads the horizon-limited popularity data/feats_new/train/it_hist_hz_{all,et1..et4} in place of the it_hist_*_luo xt columns (same attach_xt scaling); feature_stats, selection holdout, val / test and the saved holdout preds are unchanged; extra file preds/holdout/nn_<v>_holdout_hz.npy')
    p.add_argument('--val_mix', type=float, default=0.0, help="wave-5 valcd (D1 val-in-cooldown, cd_arms7.py): P > 0: from the cooldown start every NON-pool step trains w.p. P on a batch of LABELLED VAL feeds of the folds != --val_fold (nn/finetune.py's user-grouped 5-fold split; the own fold is never trained on = the OOF read), random-like domain token, p_random 1 (aux weight 0); the m02 pool draws / batches are unchanged; 0 = off")
    p.add_argument('--val_fold', type=int, default=-1, help='wave-5 valcd: the held-out (OOF) val fold 0-4 (with --val_mix)')
    p.add_argument('--rdrop_cd', type=float, default=0.0, help='wave-7 R-Drop (cd_arms8.py): alpha > 0: on cooldown steps a second dropout pass of the same batch; loss = 0.5 (L1 + L2) + alpha * feed-normalised symmetric KL of the two listwise softmaxes')
    p.add_argument('--sam_cd', type=float, default=0.0, help='wave-7 SAM (cd_arms8.py): rho > 0: on cooldown steps the optimiser step uses the gradient at w + rho g1/||g1||_2 (g1 = grad of main + aux at w; w restored exactly)')
    p.add_argument('--xoff', type=float, default=0.0, help='wave-10 R2 XOFF (cd_arms10.py): A > 0 adds A * g_noend[clamp(pos, 0, 299)] to the MAIN listwise logits of the exploration training feeds (NN p_random > 0.5) in every training batch; never on the K9 aux or at eval / prediction; 0 = off (arm value 0.5)')
    p.add_argument('--xoff_table', type=str, default=XOFF_TABLE, help='wave-10 R2 XOFF: json with g_noend[300] = log within-feed positive-rate lift by displayed pos on the exploration train feeds, last shown item excluded (premise/premise_g.py)')
    return p

def parse_args(argv):
    return parse().parse_args(argv)
